insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'rules','노사협의회 운영규약(2025.06.17)','<div class="box" style="margin-bottom:16px"><b>노사협의회 운영규약</b> · 작성자 정지선 · 게시일 2025-06-25<br><a href="https://grilu.kr/archive/rules/000000n0u.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">2025년 제2차 노사협의회 의결에 따라, 운영규약 제32조(고충처리위원회의 구성) 제1항 개정하여 게시합니다. (개정전) 제32조(고충처리위원회의 구성) ① 고충처리위원은 협의회 위원 중에서 호선하여 노사를 대표하는 3인 이내로 한다. (개정 2024.06.25.) (개정후) 제32조(고충처리위원회의 구성) ① 고충처리위원은 2명으로 하며 다음 각 호와 같다. &lt;개정 2025.06.17.&gt;             1. 부원장             2. 근로자위원 중 1명을 호선하되, 과반수로 조직된 노동조합이 있는 경우 노동조합 대표자</p><p class="note">첨부: 노사협의회 운영규약(일부개정)_250617.pdf</p>','정지선',false,'{"legacy_id": "gw-000000n0u", "page": "archive/rules/000000n0u.html", "files": ["노사협의회 운영규약(일부개정)_250617.pdf"], "source": "gw.gri.re.kr 노사협의회 운영규약"}'::jsonb,'2025-06-25'::date,'2025-06-25'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000n0u');
