insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'committee','25-1차 심의위원회 상정(안) 게시 및 직원 의견청취 안내','<div class="box" style="margin-bottom:16px"><b>심의위원회 상정(안)</b> · 작성자 장소희 · 게시일 2025-02-17<br><a href="https://grilu.kr/gri/committee/000000mmh.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">심의위원회 상정(안)을 붙임과 같이 게시합니다. 
