insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'director','경기연구원 노동이사 선출을 위한 ''입후보자 및 선거일정'' 공고','<div class="box" style="margin-bottom:16px"><b>노동이사 활동보고</b> · 작성자 이용원 · 게시일 2024-10-21<br><a href="https://grilu.kr/gri/director/000000lrn.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 노동이사 선출을 위한 &#x27;입후보자 및 선거일정&#x27;을 아래와 같이 공고합니다.   상세한 내용은 첨부파일을 참조하여 주시기 바랍니다. □ 노동이사 입후보자   ⋅ 기호 1번 : 경제사회연구실 선임연구위원 문미성   ⋅ 기호 2번 : 전략연구센터 선임연구위원 김정훈 □ 노동이사 선거일정   ⋅ 선거 운동기간 : 2024.10.22.(화) ~ 10.29.(화) 24:00   ⋅ 선거일시 : 2024.10.30.(수) 08:00 ~ 18:00   ⋅ 선거권자 : 선거인명부작성일(10.3) 기준 재직 중인 직원 208명   ⋅ 선거방법 : 전자투표(그룹웨어사용)를 이용한 무기명 투표   ⋅ 선출방법 : 유효투표의 다수를 얻은 자 순으로 2인 선출하되,                    득표수가 동일한 경우에는 장기근속자, 연장자 순으로 결정   2024년  10월  21일   경기연구원 노동이사 선거관리위원장</p><p class="note">첨부: 노동이사 입후보자 선거공고.pdf</p>','이용원',false,'{"legacy_id": "gw-000000lrn", "page": "gri/director/000000lrn.html", "files": ["노동이사 입후보자 선거공고.pdf"], "source": "gw.gri.re.kr 노동이사 활동보고"}'::jsonb,'2024-10-21'::date,'2024-10-21'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000lrn');
