insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'council','GRI노사협의회 근로자위원 입후보자 확정 및 선거일정 공고(연구직군)','<div class="box" style="margin-bottom:16px"><b>공고 및 회의록</b> · 작성자 조영진 · 게시일 2022-03-31<br><a href="https://grilu.kr/archive/council/000000jj7.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">GRI노사협의회 근로자위원 입후보자 확정 및 선거일정 공고(연구직군) GRI노사협의회 연구직군 근로자위원 입후보 결과에 따른 선거를 아래와 같이 실시함을 공고합니다. - 아 래 - □ 선거명 노사협의회 근로자위원 선출 보궐선거(연구직군) □ 선출 근로자위원 수 -연구직군 2명 ※선출 근로자위원의 임기는 ~22.8.19까지 □ 근로자위원 입후보자 -생태환경연구실 이양주(선임연구위원) -교통물류연구실 김채만(선임연구위원) □ 선거일정 1) 선거일시 : 2022.4.1.(금) 09:00~18:00 2) 선거방법 : 전자투표 시행(그룹웨어사용) 3) 선거권자 : 22.3.31일 기준 재직중인 연구직 직원 58명 (부서장 제외, 공투센터 연구직 및 초빙연구직 포함) 4) 근로자위원 선출인원과 입후보 인원이 동일하여 찬반투표 실시, 유효투표 중 과반수의 찬성으로 근로자 위원 선출결정 2022. 3. 31 GRI노사협의회 선거관리위원회</p><p class="note">첨부: 220331 근로자위원 입후보자 확정 및 선거일정 공고(연구직군).hwp</p>','조영진',false,'{"legacy_id": "gw-000000jj7", "page": "archive/council/000000jj7.html", "files": ["220331 근로자위원 입후보자 확정 및 선거일정 공고(연구직군).hwp"], "source": "gw.gri.re.kr 공고 및 회의록"}'::jsonb,'2022-03-31'::date,'2022-03-31'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000jj7');
