insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'council','GRI노사협의회 근로자위원 입후보자 확정 및 선거일정 공고(관리·정보·기능직군)','<div class="box" style="margin-bottom:16px"><b>공고 및 회의록</b> · 작성자 조영진 · 게시일 2022-01-24<br><a href="https://grilu.kr/archive/council/000000jdp.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">GRI노사협의회 근로자위원 입후보자 확정 및 선거일정 공고(관리·정보·기능직군) GRI노사협의회 관리·정보·기능직군 근로자위원 입후보 결과에 따른 선거를 아래와 같이 실시함을 공고합니다. - 아 래 - □ 선거명    노사협의회 근로자위원 선출 보궐선거(관리·정보·기능직군) □ 선출 근로자위원 수    -관리직군 1명    ※선출 근로자위원의 임기는 ~22.8.19까지 □ 근로자위원 입후보자    -성과관리부 민경진(관리 5급) □ 선거일정    1) 선거일시 : 2022.1.25.(화) 09:00~18:00    2) 선거방법 : 전자투표 시행(그룹웨어사용)    3) 선거권자 : 22.1.24일 기준 재직중인 관리·정보·기능직 직원 27명(부서장 제외)    ※근로자위원 선출인원과 입후보 인원이 동일할 경우 찬반투표를 실시하며,      유효투표 중 과반수의 찬성으로 근로자 위원 선출결정 2022. 1. 24 GRI노사협의회 선거관리위원회</p><p class="note">첨부: 220124 근로자위원 입후보자 확정 및 선거일정 공고.hwp</p>','조영진',false,'{"legacy_id": "gw-000000jdp", "page": "archive/council/000000jdp.html", "files": ["220124 근로자위원 입후보자 확정 및 선거일정 공고.hwp"], "source": "gw.gri.re.kr 공고 및 회의록"}'::jsonb,'2022-01-24'::date,'2022-01-24'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000jdp');
