insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'director','경기연구원 노동이사 공개모집 재공고','<div class="box" style="margin-bottom:16px"><b>노동이사 활동보고</b> · 작성자 송성종 · 게시일 2021-11-22<br><a href="https://grilu.kr/gri/director/000000j55.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 노동이사 선출을 위한 모집 공고가 진행중이니 직원분들께서는 많은 참여 부탁드립니다. -------------------------------------------------------------------------------------------------- 경기연구원은 노동자의 현장 경험과 노하우를 경영에 접목함으로써 경영투명성과 공익성을 확보하고자 아래와 같이 노동이사를 공개 모집합니다. 1.공모직위 및 인원         - 경기연구원 노동이사 1명 2.접수방법         - 접수기간 : 2021. 11. 22.(월) ~ 11. 29.(월) 18:00, 7일간         - 접수방법 : 방문 및 우편접수         - 접 수 처 : 경기연구원 행정지원부           * 주소 : 경기도 수원시 장안구 경수대로 1150 606호(경기연구원 행정지원부)         - 문 의 처 : 경기연구원 행정지원부(031-250-3208) 자세한 사항은 공고문을 확인하여 주시기 바랍니다.</p><p class="note">첨부: 노동이사제 입후보자 공개모집 재공고문.hwp</p>','송성종',false,'{"legacy_id": "gw-000000j55", "page": "gri/director/000000j55.html", "files": ["노동이사제 입후보자 공개모집 재공고문.hwp"], "source": "gw.gri.re.kr 노동이사 활동보고"}'::jsonb,'2021-11-22'::date,'2021-11-22'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000j55');
