insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'council','취업규칙 일부 개정규칙 공포','<div class="box" style="margin-bottom:16px"><b>공고 및 회의록</b> · 작성자 장영자 · 게시일 2020-04-01<br><a href="https://grilu.kr/archive/council/000000i61.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">취업규칙 일부개정 규칙을 2020.4.1자로 공포합니다. &lt;개정 주요 내용&gt; ○ 「남녀고용평등과 일·가정양립지원에관한법률」제18조의2(배우자출산휴가)개정(시행일 2019.10.1.)에 따라 특별휴가 중 ‘배우자출산휴가 일수 10일’로 변경      (취업규칙 제22조 제1항 관련 [별표1]) ○ 「근로기준법」 제93조(취업규칙의 작성·신고)에 의거 취업규칙 의무명시 사항인 임금산정기간을 ‘매월 초일부터 말일까지’로 구체적 명시      (취업규칙 제51조) ○ 「근로기준법」 제93조(취업규칙의 작성·신고)에 의거 취업규칙 의무명시 사항인 직장 내 괴롭힘 금지  ‘1년에 1회 이상 예방교육 실시’ 등 예방조치의무 명확화      (취업규칙 제57조)</p><p class="note">첨부: 취업규칙 일부개정 공포문(2020.4.1).pdf, 경기연구원 취업규칙(전문)(2020.4.1).pdf</p>','장영자',false,'{"legacy_id": "gw-000000i61", "page": "archive/council/000000i61.html", "files": ["취업규칙 일부개정 공포문(2020.4.1).pdf", "경기연구원 취업규칙(전문)(2020.4.1).pdf"], "source": "gw.gri.re.kr 공고 및 회의록"}'::jsonb,'2020-04-01'::date,'2020-04-01'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000i61');
update public.posts set board='council', title='취업규칙 일부 개정규칙 공포', content='<div class="box" style="margin-bottom:16px"><b>공고 및 회의록</b> · 작성자 장영자 · 게시일 2020-04-01<br><a href="https://grilu.kr/archive/council/000000i61.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">취업규칙 일부개정 규칙을 2020.4.1자로 공포합니다. &lt;개정 주요 내용&gt; ○ 「남녀고용평등과 일·가정양립지원에관한법률」제18조의2(배우자출산휴가)개정(시행일 2019.10.1.)에 따라 특별휴가 중 ‘배우자출산휴가 일수 10일’로 변경      (취업규칙 제22조 제1항 관련 [별표1]) ○ 「근로기준법」 제93조(취업규칙의 작성·신고)에 의거 취업규칙 의무명시 사항인 임금산정기간을 ‘매월 초일부터 말일까지’로 구체적 명시      (취업규칙 제51조) ○ 「근로기준법」 제93조(취업규칙의 작성·신고)에 의거 취업규칙 의무명시 사항인 직장 내 괴롭힘 금지  ‘1년에 1회 이상 예방교육 실시’ 등 예방조치의무 명확화      (취업규칙 제57조)</p><p class="note">첨부: 취업규칙 일부개정 공포문(2020.4.1).pdf, 경기연구원 취업규칙(전문)(2020.4.1).pdf</p>', attachments='{"legacy_id": "gw-000000i61", "page": "archive/council/000000i61.html", "files": ["취업규칙 일부개정 공포문(2020.4.1).pdf", "경기연구원 취업규칙(전문)(2020.4.1).pdf"], "source": "gw.gri.re.kr 공고 및 회의록"}'::jsonb where attachments->>'legacy_id' = 'gw-000000i61' and (board <> 'council' or attachments->>'page' <> 'archive/council/000000i61.html');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'director','경기연구원 노동이사 공개모집 3차 재공고 안내','<div class="box" style="margin-bottom:16px"><b>노동이사 활동보고</b> · 작성자 이대민 · 게시일 2020-03-17<br><a href="https://grilu.kr/gri/director/000000i52.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문·첨부파일 전문 보기</a></div><p style="line-height:1.8;color:#444">경기연구원 노동이사 선출을 위한 모집 3차 재공고가 진행중이니 직원분들께서는 많은 참여 부탁드립니다. - 경기연구원은 노동자의 현장 경험과 노하우를 경영에 접목함으로써 경영투명성과 공익성을 확보하고자 아래와 같이 노동이사를 공개 모집합니다. 1.공모직위 및 인원         - 경기연구원 노동이사 1명 2.접수방법         - 접수기간 : 2020. 03. 18.(수) ~ 04. 01.(수) 18:00, 15일간         - 접수방법 : 방문 및 우편접수         - 접 수 처 : 경기연구원 행정지원부           * 주소 : 경기도 수원시 장안구 경수대로 1150 606호(경기연구원 행정지원부)         - 문 의 처 : 경기연구원 행정지원부(031-250-3186) 자세한 사항은 공고문을 확인하여 주시기 바랍니다.</p><p class="note">첨부: 노동이사제 입후보자 공개모집 3차 재공고문.hwp</p>','이대민',false,'{"legacy_id": "gw-000000i52", "page": "gri/director/000000i52.html", "files": ["노동이사제 입후보자 공개모집 3차 재공고문.hwp"], "source": "gw.gri.re.kr 노동이사 활동보고"}'::jsonb,'2020-03-17'::date,'2020-03-17'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-000000i52');
